DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    -- Delete existing CAM 13 if any
    DELETE FROM public.topics WHERE name = 'CAM 13' AND user_id IS NULL;
    
    -- Insert CAM 13 topic
    VALUES (gen_random_uuid(), NULL, 'CAM 13', 'school', 'CAM', NOW() + interval '3 seconds')
    RETURNING id INTO v_topic_id;
    
END $$;